[metadata] {"filePath": "/workspace/repo/extensions/copilot/src/extension/chatSessions/claude/common/claudeMessageDispatch.ts", "oldString": "function processToolResult(
	toolResult: Anthropic.Messages.ToolResultBlockParam,
	accessor: ServicesAccessor,
	sessionId: string,
	request: MessageHandlerRequestContext,
	state: MessageHandlerState,
): void {", "newString": "/**
 * Emits a `languageModelToolInvoked` telemetry event for a completed tool call,
 * mirroring the workbench LanguageModelToolsService event.
 *
 * @param telemetryService Service used to send the Microsoft telemetry event.
 * @param sessionId The current chat session identifier.
 * @param toolUse The tool_use block matched to this result.
 * @param toolResult The tool_result block being processed.
 * @param toolStartTimes Map of tool call ID to invocation start timestamp (ms).
 */
function sendToolInvokedTelemetry(
	telemetryService: ITelemetryService,
	sessionId: string,
	toolUse: Anthropic.Beta.Messages.BetaToolUseBlock,
	toolResult: Anthropic.Messages.ToolResultBlockParam,
	toolStartTimes: Map<string, number>,
): void {
	let result: 'success' | 'error' | 'userCancelled';
	if (toolResult.is_error) {
		result = 'error';
	} else if (toolResult.content === DENY_TOOL_MESSAGE) {
		result = 'userCancelled';
	} else {
		result = 'success';
	}

	const toolSourceKind = toolUse.name.startsWith('mcp__') ? 'mcp' : 'claudeCode';

	const startTime = toolStartTimes.get(toolUse.id);
	let measurements: TelemetryEventMeasurements | undefined;
	if (startTime !== undefined) {
		measurements = { invocationTimeMs: Math.max(0, Date.now() - startTime) };
		toolStartTimes.delete(toolUse.id);
	}

	/* __GDPR__
		"languageModelToolInvoked" : {
			"owner": "zhichli",
			"comment": "Provides insight into the usage of language model tools (Claude Code agent).",
			"result": { "classification": "SystemMetaData", "purpose": "FeatureInsight", "comment": "success | error | userCancelled" },
			"chatSessionId": { "classification": "SystemMetaData", "purpose": "FeatureInsight", "comment": "The chat session resource id." },
			"toolId": { "classification": "SystemMetaData", "purpose": "FeatureInsight", "comment": "The SDK tool name (e.g. Read, Bash, Edit)." },
			"toolExtensionId": { "classification": "SystemMetaData", "purpose": "FeatureInsight", "comment": "Always undefined for Claude Code." },
			"toolSourceKind": { "classification": "SystemMetaData", "purpose": "FeatureInsight", "comment": "claudeCode | mcp" },
			"invocationTimeMs": { "classification": "SystemMetaData", "purpose": "PerformanceAndHealth", "isMeasurement": true, "comment": "Time between tool invocation and tool result (includes any permission wait)." }
		}
	*/
	telemetryService.sendMSFTTelemetryEvent('languageModelToolInvoked', {
		result,
		chatSessionId: `claude-code:/${sessionId}`,
		toolId: toolUse.name,
		toolExtensionId: undefined,
		toolSourceKind,
